import type { ReactNode } from "react";

/** Honest labelling: the prototype uses rules, not a live AI service. */
export function DemoNotice({ children }: { children?: ReactNode }) {
  return (
    <aside className="demo-notice" role="note">
      <span className="demo-notice__tag">Demo triage</span>
      <span>
        {children ??
          "Category, severity and routing are generated by clearly labelled keyword rules, not a live AI model. Officers can review and correct every recommendation."}
      </span>
    </aside>
  );
}
